#include "Groove.h"
#include <juce_cryptography/juce_cryptography.h>
#include <cmath>
namespace pulse {
using namespace juce;
namespace {
bool number(const var& v){return(v.isInt()||v.isInt64()||v.isDouble())&&std::isfinite((double)v);}
Result rowsValid(const std::vector<GroovePreset>& rows){if(rows.size()>maxGroovePresets)return Result::fail("The groove library supports 128 personal presets.");std::set<String> ids,names;for(const auto& p:rows){auto valid=validateGroovePreset(p);if(valid.failed())return valid;if(!ids.insert(p.id).second||!names.insert(p.name.toLowerCase()).second)return Result::fail("Groove identities and names must be unique.");}return Result::ok();}
}
Result validateGroovePreset(const GroovePreset& p){if(p.id.isEmpty()||p.id.length()>64||!p.id.containsOnly("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_")||p.name.isEmpty()||p.name.length()>64||p.name.trim()!=p.name)return Result::fail("Use a valid groove identity and a trimmed name of 1-64 characters.");for(auto c:p.name)if(c<32||c==127)return Result::fail("Groove names cannot contain control characters.");return validateGroove(p.settings);}
var groovePresetToJson(const GroovePreset& p){auto* row=new DynamicObject();row->setProperty("id",p.id);row->setProperty("name",p.name);auto* settings=new DynamicObject();settings->setProperty("grid",p.settings.pattern.grid);settings->setProperty("timing",p.settings.timing);settings->setProperty("velocity",p.settings.velocity);settings->setProperty("window",p.settings.window);settings->setProperty("useWindow",p.settings.useWindow);Array<var> steps;for(const auto& step:p.settings.pattern.steps){auto* item=new DynamicObject();item->setProperty("offset",step.offset);item->setProperty("velocity",step.velocity);item->setProperty("active",step.active);steps.add(var(item));}settings->setProperty("steps",steps);row->setProperty("settings",var(settings));return var(row);}
Result groovePresetFromJson(const var& row,GroovePreset& output){
    if(!row.getDynamicObject()||!row["id"].isString()||!row["name"].isString()||!row["settings"].getDynamicObject())return Result::fail("Invalid groove preset object.");GroovePreset next;next.id=row["id"].toString();next.name=row["name"].toString();auto settings=row["settings"];auto* steps=settings["steps"].getArray();if(!steps||steps->size()<2||steps->size()>32||!settings["useWindow"].isBool())return Result::fail("Invalid groove cells or window mode.");for(auto key:{"grid","timing","velocity","window"})if(!number(settings[key]))return Result::fail("Missing or invalid groove setting.");next.settings.pattern.grid=(double)settings["grid"];next.settings.timing=(double)settings["timing"];next.settings.velocity=(double)settings["velocity"];next.settings.window=(double)settings["window"];next.settings.useWindow=(bool)settings["useWindow"];next.settings.pattern.steps.clear();
    for(const auto& step:*steps){if(!step.getDynamicObject()||!number(step["offset"])||!number(step["velocity"])||!step["active"].isBool()||(double)step["velocity"]<0||(double)step["velocity"]>1)return Result::fail("Invalid groove cell.");next.settings.pattern.steps.push_back({(double)step["offset"],(float)(double)step["velocity"],(bool)step["active"]});}auto valid=validateGroovePreset(next);if(valid.failed())return valid;output=std::move(next);return Result::ok();
}
String groovePresetToken(const File& file){if(file.isSymbolicLink())return "unavailable";if(!file.exists())return "missing";if(!file.existsAsFile()||file.getSize()>maxGroovePresetBytes)return "unavailable";return SHA256(file).toHexString();}
Result loadGroovePresets(const File& file,std::vector<GroovePreset>& output){if(file.isSymbolicLink())return Result::fail("Choose an ordinary groove file.");if(!file.exists()){output.clear();return Result::ok();}if(!file.existsAsFile()||file.getSize()>maxGroovePresetBytes)return Result::fail("Groove files must be ordinary files up to 1 MiB.");var json;auto valid=JSON::parse(file.loadFileAsString(),json);if(valid.failed())return Result::fail("Cannot read groove presets; existing file retained.");auto* rows=json["presets"].getArray();if(!json.getDynamicObject()||!json["schema"].isInt()||(int)json["schema"]!=1||json["application"].toString()!="Pulse Studio grooves"||!rows||rows->size()>maxGroovePresets)return Result::fail("Unsupported groove preset file.");std::vector<GroovePreset> next;for(const auto& row:*rows){GroovePreset p;valid=groovePresetFromJson(row,p);if(valid.failed())return valid;next.push_back(std::move(p));}valid=rowsValid(next);if(valid.failed())return valid;output=std::move(next);return Result::ok();}
Result saveGroovePresets(const File& file,const std::vector<GroovePreset>& rows,const String& expected){auto valid=rowsValid(rows);if(valid.failed())return valid;auto token=groovePresetToken(file);if(token=="unavailable"||(!expected.isEmpty()&&token!=expected))return Result::fail("Groove file changed or is unavailable. Reopen Presets.");auto* json=new DynamicObject();json->setProperty("schema",1);json->setProperty("application","Pulse Studio grooves");Array<var> presets;for(const auto& p:rows)presets.add(groovePresetToJson(p));json->setProperty("presets",presets);auto text=JSON::toString(var(json),false,22);if(text.getNumBytesAsUTF8()>maxGroovePresetBytes)return Result::fail("Groove file is too large.");valid=file.getParentDirectory().createDirectory();if(valid.failed())return valid;TemporaryFile temp(file);if(!temp.getFile().replaceWithText(text))return Result::fail("Cannot write groove presets.");std::vector<GroovePreset> checked;valid=loadGroovePresets(temp.getFile(),checked);if(valid.failed()||checked.size()!=rows.size())return Result::fail("Groove staging verification failed; existing file retained.");for(size_t i=0;i<rows.size();++i)if(JSON::toString(groovePresetToJson(checked[i]),true,22)!=JSON::toString(groovePresetToJson(rows[i]),true,22))return Result::fail("Groove staging changed its settings; existing file retained.");if(groovePresetToken(file)!=token)return Result::fail("Groove file changed during save. Existing file retained.");if(!temp.overwriteTargetFileWithTemporary())return Result::fail("Cannot publish groove presets. Existing file retained.");return Result::ok();}
Result putGroovePreset(const File& file,const GroovePreset& p,bool replace,const String& expected){auto valid=validateGroovePreset(p);if(valid.failed())return valid;auto token=groovePresetToken(file);if(!expected.isEmpty()&&token!=expected)return Result::fail("Groove library changed. Reopen Presets.");std::vector<GroovePreset> rows;valid=loadGroovePresets(file,rows);if(valid.failed())return valid;auto found=std::find_if(rows.begin(),rows.end(),[&](const auto& row){return row.id==p.id;});if(replace){if(found==rows.end())return Result::fail("Groove preset was removed. Reopen Presets.");*found=p;}else{if(found!=rows.end())return Result::fail("Groove identity already exists.");rows.push_back(p);}return saveGroovePresets(file,rows,token);}
Result removeGroovePreset(const File& file,const String& id,const String& expected){auto token=groovePresetToken(file);if(!expected.isEmpty()&&token!=expected)return Result::fail("Groove library changed. Reopen Presets.");std::vector<GroovePreset> rows;auto valid=loadGroovePresets(file,rows);if(valid.failed())return valid;auto found=std::find_if(rows.begin(),rows.end(),[&](const auto& row){return row.id==id;});if(found==rows.end())return Result::fail("Groove preset no longer exists.");rows.erase(found);return saveGroovePresets(file,rows,token);}
std::vector<GroovePreset> factoryGroovePresets(){std::vector<GroovePreset> rows;auto add=[&](const char* id,const char* name,double swing){GroovePreset p;p.id=id;p.name=name;p.settings.velocity=.35;for(size_t i=0;i<p.settings.pattern.steps.size();++i){p.settings.pattern.steps[i].offset=i%2?swing:0;p.settings.pattern.steps[i].velocity=i%4==0?1.f:i%2?.6f:.8f;}rows.push_back(p);};add("factory-groove-straight","Straight sixteenth accents",0);add("factory-groove-light","Light sixteenth swing",.18);add("factory-groove-triplet","Triplet-feel sixteenths",1./3);add("factory-groove-late","Laid-back backbeat",0);for(size_t i=0;i<16;++i)if(i%8==4)rows.back().settings.pattern.steps[i].offset=.12;add("factory-groove-push","Pushed offbeats",-.12);add("factory-groove-broken","Broken sixteenth pocket",0);const double offsets[]={0,.12,-.06,.16,0,-.08,.1,.2};for(size_t i=0;i<16;++i)rows.back().settings.pattern.steps[i].offset=offsets[i%8];return rows;}
}
